#include <stdint.h>
#include <stdio.h>
#include "stm32f4xx.h"

void delay (void)
{
	for(volatile unsigned int i=0;i<100000;i++);
}

int main (void)
{
	RCC->AHB1ENR|=(1<<0);

	GPIOA->MODER &=~(3<<(5*2));
	GPIOA->MODER |=(1<<(5*2));

	while(1)
	{
		GPIOA->ODR|=(1<<5);
		delay();
		GPIOA->ODR&=~(1<<5);
		delay();

	}
}

